+              field: my_vector
+              query_vector: [ 1, 1, 1, 1 ]
+              k: 5
+
+  - match: { hits.total.value: 5 } # collector sees k docs
+  - length: { hits.hits: 3 } # size docs retrieved
+  - match: { hits.hits.0._id: "1" }
+  - match: { hits.hits.1._id: "2" }
+  - match: { hits.hits.2._id: "3" }
+
+  - do:
